import{_ as i,C as l,o as e,c as n,a2 as t,b as s,w as o,a as E,E as C,a3 as B}from"./chunks/framework.CZGNF-7T.js";const _=JSON.parse('{"title":"워크스페이스 관리 (Workspace Master)","description":"","frontmatter":{},"headers":[],"relativePath":"work-setting/ws-manage.md","filePath":"work-setting/ws-manage.md","lastUpdated":1788532527000}'),A={name:"work-setting/ws-manage.md"};function d(c,a,h,u,g,m){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="워크스페이스-관리-workspace-master" tabindex="-1">워크스페이스 관리 (Workspace Master) <a class="header-anchor" href="#워크스페이스-관리-workspace-master" aria-label="Permalink to &quot;워크스페이스 관리 (Workspace Master)&quot;">​</a></h1><blockquote><p><strong>워크스페이스 관리</strong> 페이지는 시스템 관리자가 회사 내 모든 협업 공간(본사 관리, 부동산 개발 프로젝트, 기타 공간)의 계층 구조와 생애주기를 전사적 관점에서 총괄 제어하는 마스터 관리 대시보드입니다.</p></blockquote><h2 id="_1-개요-및-관리자-허브" tabindex="-1">1. 개요 및 관리자 허브 <a class="header-anchor" href="#_1-개요-및-관리자-허브" aria-label="Permalink to &quot;1. 개요 및 관리자 허브&quot;">​</a></h2><p>개별 워크스페이스 내부의 <a href="/work-manage/settings.html">설정</a> 메뉴와 달리, 전사 레벨에서 운영 중인 모든 워크스페이스를 한눈에 파악하고 신규 개설, 복제, 잠금보관(아카이빙), 안전 삭제를 일괄 처리합니다.</p>',4)),(e(),s(B,null,{default:o(()=>[C(r,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20%EC%83%9D%EC%95%A0%EC%A3%BC%EA%B8%B0%EC%A0%9C%EC%96%B4%20%5B%22%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%83%9D%EC%95%A0%EC%A3%BC%EA%B8%B0%20%EA%B4%80%EB%A6%AC%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%E2%9E%95%20%EC%83%88%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EA%B0%9C%EC%84%A4%3Cbr%3E(%EA%B8%B0%EB%B3%B8%20%EC%83%9D%EC%84%B1%20%EB%98%90%EB%8A%94%20%EA%B8%B0%EC%A1%B4%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EB%B3%B5%EC%A0%9C)%22%5D%20--%3E%20B%5B%22%F0%9F%9F%A2%20%EC%A0%95%EC%83%81%20%EC%9A%B4%EC%98%81%20(Active)%3Cbr%3E(%EB%AA%A8%EB%93%88%20%EC%97%B0%EB%8F%99%20%26%20%EA%B3%84%EC%B8%B5%ED%98%95%20%ED%8A%B8%EB%A6%AC)%22%5D%0A%20%20%20%20%20%20%20%20B%20--%3E%20C%5B%22%F0%9F%9F%A1%20%EC%9E%A0%EA%B8%88%EB%B3%B4%EA%B4%80%20(Archive)%3Cbr%3E(%EC%9D%BC%EB%B0%98%20%EC%A0%91%EA%B7%BC%20%EC%B0%A8%EB%8B%A8%20%2F%20%EC%9D%B4%EB%A0%A5%20%EB%B3%B4%EC%A1%B4)%22%5D%0A%20%20%20%20%20%20%20%20B%20%26%20C%20--%3E%20D%5B%22%F0%9F%97%91%EF%B8%8F%20%EC%95%88%EC%A0%84%20%EC%82%AD%EC%A0%9C%3Cbr%3E(%EC%8B%9D%EB%B3%84%EC%9E%90%20%ED%99%95%EC%9D%B8%20%2F%20%EC%9D%B4%EB%A0%A5%20%EC%9E%88%EC%9D%84%20%EC%8B%9C%20%EC%9E%A0%EA%B8%88%EB%B3%B4%EA%B4%80%20%EC%9E%90%EB%8F%99%20%EC%A0%84%ED%99%98)%22%5D%0A%20%20%20%20end%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="_2-워크스페이스-목록-그리드-및-시각화" tabindex="-1">2. 워크스페이스 목록 그리드 및 시각화 <a class="header-anchor" href="#_2-워크스페이스-목록-그리드-및-시각화" aria-label="Permalink to &quot;2. 워크스페이스 목록 그리드 및 시각화&quot;">​</a></h2><p>전체 워크스페이스를 트리 계층과 상태 배지로 직관적으로 표현합니다.</p><h3 id="🌲-계층형-트리-구조-depth-indentation" tabindex="-1">🌲 계층형 트리 구조 (Depth Indentation) <a class="header-anchor" href="#🌲-계층형-트리-구조-depth-indentation" aria-label="Permalink to &quot;🌲 계층형 트리 구조 (Depth Indentation)&quot;">​</a></h3><ul><li>상위 워크스페이스와 하위 워크스페이스의 상속 관계가 화살표(<i class="mdi mdi-chevron-right text-grey"></i>)와 들여쓰기로 시각화되어 본사-사업지 간의 지배구조를 파악하기 쉽습니다.</li></ul><h3 id="🏷️-상태-및-식별-배지" tabindex="-1">🏷️ 상태 및 식별 배지 <a class="header-anchor" href="#🏷️-상태-및-식별-배지" aria-label="Permalink to &quot;🏷️ 상태 및 식별 배지&quot;">​</a></h3><ul><li><strong>내 워크스페이스</strong> (<i class="mdi mdi-account-tag text-success"></i>): 로그인한 사용자가 구성원으로 참여 중인 공간 표시</li><li><strong>비공개 워크스페이스</strong> (<i class="mdi mdi-lock text-blue-grey"></i>): 초대된 멤버만 접근 가능한 보안 공간</li><li><strong>북마크</strong> (<i class="mdi mdi-bookmark text-info"></i>): 즐겨찾기로 등록된 워크스페이스</li><li><strong>잠금/닫힘 상태</strong>: 이미 마감되었거나 잠금보관된 워크스페이스는 전체 행이 회색 텍스트로 감쇄되어 활성 공간과 명확히 구분됩니다.</li></ul><h3 id="📋-컬럼-커스터마이징-column-selector" tabindex="-1">📋 컬럼 커스터마이징 (Column Selector) <a class="header-anchor" href="#📋-컬럼-커스터마이징-column-selector" aria-label="Permalink to &quot;📋 컬럼 커스터마이징 (Column Selector)&quot;">​</a></h3><p>우측 상단의 컬럼 선택기를 통해 그리드에 표출할 항목을 자유롭게 지정할 수 있으며, 설정값은 브라우저에 영구 저장됩니다:</p><ul><li><strong>제공 컬럼</strong>: 이름(고정), 식별자(<code>Slug</code>), 설명, 상태, 홈페이지, 상위 워크스페이스, 공개 여부, 등록일, 수정일</li></ul><h3 id="🔍-잠금보관-항목-포함-검색" tabindex="-1">🔍 잠금보관 항목 포함 검색 <a class="header-anchor" href="#🔍-잠금보관-항목-포함-검색" aria-label="Permalink to &quot;🔍 잠금보관 항목 포함 검색&quot;">​</a></h3><ul><li>기본적으로 정상 운영 중인 워크스페이스만 조회되지만, 검색 옵션의 **&#39;잠금보관 포함&#39;**을 체크하면 과거 종료되거나 보관 처리된 워크스페이스까지 포함하여 검색할 수 있습니다.</li></ul><h2 id="_3-워크스페이스-생애주기-제어-actions" tabindex="-1">3. 워크스페이스 생애주기 제어 (Actions) <a class="header-anchor" href="#_3-워크스페이스-생애주기-제어-actions" aria-label="Permalink to &quot;3. 워크스페이스 생애주기 제어 (Actions)&quot;">​</a></h2><p>각 행 우측의 더보기(<i class="mdi mdi-dots-horizontal"></i>) 메뉴를 통해 강력한 생애주기 제어 액션을 수행합니다. (관리자 권한 필요)</p><h3 id="➕-새-워크스페이스-생성-및-복사-copy" tabindex="-1">➕ 새 워크스페이스 생성 및 복사 (Copy) <a class="header-anchor" href="#➕-새-워크스페이스-생성-및-복사-copy" aria-label="Permalink to &quot;➕ 새 워크스페이스 생성 및 복사 (Copy)&quot;">​</a></h3><ul><li><strong>새 워크스페이스</strong>: 완전히 새로운 공간을 백지 상태에서 개설합니다.</li><li><strong>워크스페이스 복사</strong>: 기존 워크스페이스의 활성화된 모듈 구성, 이슈 트래커, 기본 설정을 그대로 복제하여 유사 사업지나 새 프로젝트를 빠르게 셋업할 수 있습니다.</li></ul><h3 id="🔒-잠금보관-archive-잠금보관-해제" tabindex="-1">🔒 잠금보관 (Archive) / 잠금보관 해제 <a class="header-anchor" href="#🔒-잠금보관-archive-잠금보관-해제" aria-label="Permalink to &quot;🔒 잠금보관 (Archive) / 잠금보관 해제&quot;">​</a></h3><ul><li><strong>잠금보관</strong>: 사업이 종료되었거나 일시 중단된 워크스페이스를 &#39;잠금보관&#39; 상태로 전환합니다. 일반 구성원의 신규 접근 및 데이터 수정이 전면 차단되지만, 과거 데이터는 안전하게 보존됩니다.</li><li><strong>보관 해제</strong>: 필요시 원클릭으로 잠금보관을 해제하여 정상 운영 상태로 즉시 복원할 수 있습니다.</li></ul><h3 id="🗑️-2단계-안전-삭제-및-이력-보호-정책" tabindex="-1">🗑️ 2단계 안전 삭제 및 이력 보호 정책 <a class="header-anchor" href="#🗑️-2단계-안전-삭제-및-이력-보호-정책" aria-label="Permalink to &quot;🗑️ 2단계 안전 삭제 및 이력 보호 정책&quot;">​</a></h3><ul><li><strong>식별자 검증</strong>: 실수로 인한 삭제를 방지하기 위해 해당 워크스페이스의 <strong>고유 식별자(<code>Slug</code>)를 팝업창에 똑같이 타이핑해야만 [삭제] 버튼이 활성화</strong>됩니다.</li><li><strong>⭐️ 데이터 자동 보호 정책 (중요)</strong>: <ul><li>업무(Issue), 회의(Meeting), 문서(Document) 등 단 1건이라도 활동 이력이 존재하는 워크스페이스는 물리적으로 완전 삭제되지 않고, <strong>자동으로 &#39;잠금보관&#39; 상태로 안전 전환</strong>되어 데이터 유실을 방지합니다.</li></ul></li></ul><h2 id="_4-실무-운영-가이드" tabindex="-1">4. 실무 운영 가이드 <a class="header-anchor" href="#_4-실무-운영-가이드" aria-label="Permalink to &quot;4. 실무 운영 가이드&quot;">​</a></h2><ul><li><strong>템플릿 워크스페이스 활용</strong>: 표준 업무 프로세스(트래커, 범주, 기본 마일스톤)가 세팅된 &#39;표준 템플릿&#39; 워크스페이스를 하나 마련해 두고, 새 프로젝트 개설 시 <strong>[복사]</strong> 기능을 이용하면 일관된 협업 환경을 즉시 구축할 수 있습니다.</li><li><strong>정기적인 아카이빙</strong>: 완공되거나 청산된 프로젝트는 &#39;잠금보관&#39; 처리하여 목록을 슬림하게 유지하고, 검색 시 필요할 때만 &#39;잠금보관 포함&#39;으로 조회하는 것을 권장합니다.</li></ul>',21))])}const D=i(A,[["render",d]]);export{_ as __pageData,D as default};
